def _annotate_page_footnotes(
    text_blocks: list[dict[str, Any]],
    *,
    page_number: int,
    page_height: float,
    page_width: float = 0.0,
    page_drawings: list[dict[str, Any]] | None = None,
) -> list[dict[str, Any]]:
    body_font_size = _page_body_font_size(text_blocks, page_height)
    ordered = sorted(
        [
            block
            for block in text_blocks
            if str(block.get("block_type", "text") or "text") == "text"
        ],
        key=lambda block: (
            float((block.get("bbox") or [0.0, 0.0])[1]),
            float((block.get("bbox") or [0.0])[0]),
        ),
    )
    footnotes: list[dict[str, Any]] = []
    idx = 0
    while idx < len(ordered):
        block = ordered[idx]
        is_start, marker, body_text = _looks_like_footnote_start_block(
            block,
            page_height=page_height,
            body_font_size=body_font_size,
        )
        if not is_start:
            idx += 1
            continue

        source_blocks = [block]
        content_lines = [body_text]
        cursor = idx + 1
        while cursor < len(ordered) and _looks_like_footnote_continuation_block(
            ordered[cursor],
            source_blocks[-1],
            page_height=page_height,
            body_font_size=body_font_size,
        ):
            source_blocks.append(ordered[cursor])
            content_lines.append(_clean_text(str(ordered[cursor].get("text", ""))))
            cursor += 1

        source_block_ids = [
            str(item.get("block_id", "")).strip()
            for item in source_blocks
            if str(item.get("block_id", "")).strip()
        ]
        footnote_bbox = _bbox_union([list(item.get("bbox", [])) for item in source_blocks])
        footnote_id = f"fn_p{page_number}_{len(footnotes) + 1:03d}"
        footnote_text = _clean_text(" ".join(content_lines))
        separator_line = _find_footnote_separator_line(
            list(page_drawings or []),
            page_width=page_width,
            page_height=page_height,
            footnote_bbox=footnote_bbox,
        )
        footnote = {
            "footnote_id": footnote_id,
            "marker": marker,
            "page": page_number,
            "bbox": footnote_bbox,
            "text": footnote_text,
            "source_block_ids": source_block_ids,
            "footnote_signals": ["page_bottom", "small_font_marker"],
        }
        if separator_line is not None:
            footnote["separator_line_evidence"] = separator_line
            footnote["footnote_signals"].append("separator_line")
        footnotes.append(footnote)
        for source_index, source_block in enumerate(source_blocks):
            source_block["semantic_role"] = "footnote" if source_index == 0 else "footnote_continuation"
            source_block["unit_role"] = "footnote"
            source_block["footnote_id"] = footnote_id
            source_block["footnote_marker"] = marker
            source_block["footnote_text"] = footnote_text
            source_block["footnote_source_block_ids"] = list(source_block_ids)
            source_block["footnote_signals"] = list(footnote.get("footnote_signals", []) or [])
            if separator_line is not None:
                source_block["separator_line_evidence"] = dict(separator_line)
            if source_index > 0:
                source_block["footnote_continuation"] = True
        idx = cursor

    footnote_by_marker = {str(item.get("marker", "")): item for item in footnotes}
    for block in ordered:
        if str(block.get("semantic_role", "") or "") == "footnote":
            continue
        block_font_size = _text_block_font_size(block)
        linked_refs: list[dict[str, Any]] = []
        for span in block.get("spans", []) or []:
            marker = _clean_text(str(span.get("text", "")))
            footnote = footnote_by_marker.get(marker)
            if footnote is None:
                continue
            if not _looks_like_inline_footnote_ref_span(
                block,
                span,
                marker,
                block_font_size=block_font_size,
            ):
                continue
            linked_refs.append(
                {
                    "marker": marker,
                    "footnote_id": footnote["footnote_id"],
                    "bbox": list(span.get("bbox", []) or []),
                }
            )
            signals = list(footnote.get("footnote_signals", []) or [])
            if "inline_anchor" not in signals:
                footnote["footnote_signals"] = signals + ["inline_anchor"]
                for block_id in footnote.get("source_block_ids", []) or []:
                    for source_block in ordered:
                        if str(source_block.get("block_id", "")).strip() == block_id:
                            source_block["footnote_signals"] = list(footnote.get("footnote_signals", []) or [])
        if linked_refs:
            block["footnote_refs"] = linked_refs
            block["linked_footnote_ids"] = list(dict.fromkeys(ref["footnote_id"] for ref in linked_refs))
    return footnotes


def _build_heading_section_anchor(
    text_block: dict[str, Any],
    module_context: dict[str, Any] | None,
    active_section_context: dict[str, Any] | None = None,
    toc_heading_profile: dict[str, Any] | None = None,
    page_outline_context: dict[str, Any] | None = None,
    previous_text_block: dict[str, Any] | None = None,
    next_text_block: dict[str, Any] | None = None,
) -> dict[str, Any] | None:
    if str(text_block.get("block_type", "text") or "text") != "text":
        return None
    text = _clean_text(str(text_block.get("text", "")))
    if not text:
        return None
    semantic_role = str(text_block.get("semantic_role", "") or "").strip()
    if semantic_role == "reference_heading":
        return _merge_section_context(
            {
                "outline_index": "references",
                "outline_path": "references",
                "section_title": text,
                "section_level": 1,
                "anchor_source": "reference_heading",
                "anchor_confidence": 0.95,
                "anchor_page": int(text_block.get("page", 0) or 0),
                "anchor_bbox": list(text_block.get("bbox", [])),
            },
            module_context,
        )
    if semantic_role == "reference_entry":
        return None
    toc_anchor = _build_toc_aligned_body_heading_anchor(
        text_block,
        module_context,
        toc_heading_profile,
    )
    if toc_anchor is not None:
        return toc_anchor
    embedded_toc_anchor = _build_toc_embedded_visual_subheading_anchor(
        text_block,
        module_context,
        active_section_context,
        toc_heading_profile,
        previous_text_block,
        next_text_block,
    )
    if embedded_toc_anchor is not None:
        return embedded_toc_anchor
    match = _STRICT_NUMBERED_SECTION_HEADING_RE.match(text)
    if not match:
        return None
    outline_index = str(match.group("root_outline") or match.group("child_outline") or "").strip().rstrip(".")
    section_title = _clean_text(str(match.group("title") or ""))
    if not outline_index or not section_title:
        return None
    marker_candidate = classify_outline_heading_candidate(
        text,
        active_parent_marker=(active_section_context or {}).get("outline_index"),
    )
    if _looks_like_numeric_heading_fragment(outline_index, section_title):
        text_block["outline_marker_reason"] = "numeric_fragment_not_section_heading"
        return None
    advances_active_root = _single_level_outline_marker_advances_active_root(marker_candidate, active_section_context)
    if marker_candidate is not None and not advances_active_root and (
        marker_candidate.role == "body_list_item"
        or _single_level_outline_marker_belongs_to_active_body_list(marker_candidate, active_section_context)
        or _single_level_outline_marker_belongs_to_page_list_context(
            marker_candidate,
            text,
            section_title,
            page_outline_context,
            previous_text_block,
        )
    ):
        text_block["semantic_role"] = (
            "toc_entry"
            if _page_outline_context_is_contents_list(page_outline_context)
            else "body_list_item"
        )
        text_block["unit_role"] = "body"
        text_block["outline_marker_role"] = marker_candidate.role
        text_block["outline_marker_reason"] = marker_candidate.reason
        marker = getattr(marker_candidate, "marker", None)
        if marker is not None:
            text_block["outline_marker_value"] = str(getattr(marker, "normalized_marker", "") or "").strip()
        return None
    if _looks_like_date_heading_false_positive(text, outline_index, section_title):
        return None
    if _looks_like_regressive_root_heading_candidate(outline_index, active_section_context):
        return None
    return _merge_section_context(
        {
            "outline_index": outline_index,
            "outline_path": outline_index,
            "section_title": section_title,
            "section_level": outline_index.count(".") + 1,
            "anchor_source": "heading",
            "anchor_confidence": 0.97,
            "anchor_page": int(text_block.get("page", 0) or 0),
            "anchor_bbox": list(text_block.get("bbox", [])),
        },
        module_context,
    )


def _build_toc_aligned_body_heading_anchor(
    text_block: dict[str, Any],
    module_context: dict[str, Any] | None,
    toc_heading_profile: dict[str, Any] | None,
) -> dict[str, Any] | None:
    if not toc_heading_profile:
        return None
    text = _clean_text(str(text_block.get("text") or ""))
    if not text:
        return None
    bbox = _coerce_bbox(text_block.get("bbox"))
    if bbox is None:
        return None
    page = int(text_block.get("page", 0) or 0)
    if page <= 0:
        return None
    if not _looks_like_toc_aligned_body_heading_text_block(text_block):
        return None

    page_offset = int(toc_heading_profile.get("page_offset", 0) or 0)
    physical_locator = page - page_offset
    normalized_text = _normalize_toc_body_heading_text(text)
    candidates = list(toc_heading_profile.get("by_normalized_title", {}).get(normalized_text, []) or [])
    if not candidates:
        candidates = [
            candidate
            for candidate in toc_heading_profile.get("entries", []) or []
            if _toc_body_heading_titles_compatible(text, str(candidate.get("text") or ""))
        ]
    if not candidates:
        return None

    def score(candidate: dict[str, Any]) -> tuple[float, int, int]:
        candidate_locator = candidate.get("page_locator_value")
        try:
            locator_value = int(candidate_locator) if candidate_locator is not None else 0
        except (TypeError, ValueError):
            locator_value = 0
        page_match = 1.0 if locator_value and locator_value == physical_locator else 0.0
        title_score = 1.0 if normalized_text == str(candidate.get("normalized_title") or "") else 0.82
        root_bonus = 0.15 if int(candidate.get("level", 0) or 0) <= 1 else 0.0
        top_bonus = 0.12 if float(bbox[1]) <= 180.0 else 0.0
        return (page_match + title_score + root_bonus + top_bonus, int(candidate.get("sequence_entry_index", 0) or 0), locator_value)

    selected = max(candidates, key=score)
    selected_score, _, _ = score(selected)
    if selected_score < 0.95:
        return None

    outline_index = str(selected.get("outline_index") or "").strip()
    body_marker = parse_outline_heading(text)
    toc_outline_index = outline_index
    section_title = text
    if body_marker is not None and body_marker.normalized_marker:
        outline_index = body_marker.normalized_marker
        section_title = _clean_text(str(body_marker.title or "")) or text
    level = int(selected.get("level", 1) or 1)
    section_level = max(1, level)
    section_context = {
        "outline_index": outline_index,
        "outline_path": outline_index or str(selected.get("normalized_title") or normalized_text),
        "section_title": section_title,
        "section_level": section_level,
        "anchor_source": "toc_body_alignment",
        "anchor_confidence": min(0.98, 0.82 + min(0.18, selected_score / 12.0)),
        "anchor_page": page,
        "anchor_bbox": list(text_block.get("bbox", [])),
        "toc_sequence_id": str(selected.get("toc_sequence_id") or ""),
        "toc_entry_index": int(selected.get("sequence_entry_index", selected.get("entry_index", 0)) or 0),
        "toc_text": str(selected.get("text") or ""),
        "heading_profile": "toc_aligned_body_heading",
    }
    if toc_outline_index:
        section_context["toc_outline_index"] = toc_outline_index
    if selected.get("page_locator_value") is not None:
        section_context["toc_page_locator_value"] = int(selected.get("page_locator_value") or 0)
    return _merge_section_context(section_context, module_context)


def _toc_body_heading_text_has_list_marker(text: str) -> bool:
    cleaned = _clean_text(str(text or ""))
    if not cleaned:
        return False
    if _STRICT_NUMBERED_SECTION_HEADING_RE.match(cleaned):
        return False
    return bool(_TOC_BODY_HEADING_LIST_MARKER_RE.match(cleaned))


def _looks_like_short_visual_subheading_text(text: str) -> bool:
    cleaned = _clean_text(str(text or ""))
    if not cleaned or len(cleaned) > 24:
        return False
    if _toc_body_heading_text_has_list_marker(cleaned):
        return False
    if parse_outline_heading(cleaned) is not None:
        return False
    if re.search(r"[。；;!?！？：:]$", cleaned):
        return False
    cjk_count = len(re.findall(r"[\u4e00-\u9fff]", cleaned))
    if cjk_count < 2:
        return False
    non_space_count = len(re.sub(r"\s+", "", cleaned))
    return cjk_count >= max(2, int(non_space_count * 0.6))


def _toc_entry_embeds_visual_subheading(
    *,
    entry_text: str,
    active_title: str,
    subheading_text: str,
) -> bool:
    normalized_entry = _normalize_toc_body_heading_text(entry_text)
    normalized_active = _normalize_toc_body_heading_text(active_title)
    normalized_subheading = _normalize_toc_body_heading_text(subheading_text)
    if not normalized_entry or not normalized_subheading:
        return False
    if normalized_entry == normalized_subheading:
        return False
    if normalized_subheading not in normalized_entry:
        return False
    if not normalized_active:
        return True
    active_pos = normalized_entry.find(normalized_active)
    subheading_pos = normalized_entry.rfind(normalized_subheading)
    return active_pos >= 0 and subheading_pos > active_pos


def _block_vertical_gap(
    upper_block: dict[str, Any] | None,
    lower_block: dict[str, Any],
) -> float | None:
    return _postprocess_geometry._block_vertical_gap(upper_block, lower_block)


def _looks_like_standalone_embedded_visual_subheading(
    text_block: dict[str, Any],
    previous_text_block: dict[str, Any] | None,
    next_text_block: dict[str, Any] | None,
) -> bool:
    text = _clean_text(str(text_block.get("text") or ""))
    if not _looks_like_short_visual_subheading_text(text):
        return False
    bbox = _coerce_bbox(text_block.get("bbox"))
    if bbox is None:
        return False
    width = float(bbox[2]) - float(bbox[0])
    if width > 180.0:
        return False
    previous_gap = _block_vertical_gap(previous_text_block, text_block)
    next_gap = _block_vertical_gap(text_block, next_text_block) if next_text_block is not None else None
    if previous_gap is None or next_gap is None:
        return False
    if previous_gap < 3.0 or previous_gap > 48.0:
        return False
    if next_gap < -1.0 or next_gap > 36.0:
        return False
    next_text = _clean_text(str((next_text_block or {}).get("text") or ""))
    if not next_text or _toc_body_heading_text_has_list_marker(next_text):
        return False
    return True


def _build_toc_embedded_visual_subheading_anchor(
    text_block: dict[str, Any],
    module_context: dict[str, Any] | None,
    active_section_context: dict[str, Any] | None,
    toc_heading_profile: dict[str, Any] | None,
    previous_text_block: dict[str, Any] | None,
    next_text_block: dict[str, Any] | None,
) -> dict[str, Any] | None:
    if not toc_heading_profile or not active_section_context:
        return None
    if str(text_block.get("semantic_role") or "").strip() in {
        "page_number",
        "running_header",
        "page_header",
        "running_footer",
        "page_footer",
        "publication_footer",
        "reference_entry",
        "footnote",
    }:
        return None
    text = _clean_text(str(text_block.get("text") or ""))
    if not _looks_like_standalone_embedded_visual_subheading(
        text_block,
        previous_text_block,
        next_text_block,
    ):
        return None
    active_outline_index = str(active_section_context.get("outline_index") or "").strip().rstrip(".")
    if not active_outline_index or active_outline_index == "references":
        return None
    active_title = _clean_text(str(active_section_context.get("section_title") or ""))
    matching_entry: dict[str, Any] | None = None
    for entry in toc_heading_profile.get("entries", []) or []:
        if str(entry.get("outline_index") or "").strip().rstrip(".") != active_outline_index:
            continue
        if _toc_entry_embeds_visual_subheading(
            entry_text=str(entry.get("text") or ""),
            active_title=active_title,
            subheading_text=text,
        ):
            matching_entry = entry
            break
    if matching_entry is None:
        return None
    active_level = int(active_section_context.get("section_level", 0) or 0)
    if active_level <= 0:
        active_level = active_outline_index.count(".") + 1
    section_context = {
        "outline_index": active_outline_index,
        "outline_path": f"{active_outline_index} > {text}",
        "section_title": text,
        "section_level": min(active_level + 1, 6),
        "anchor_source": "toc_embedded_visual_subheading",
        "anchor_confidence": 0.9,
        "anchor_page": int(text_block.get("page", 0) or 0),
        "anchor_bbox": list(text_block.get("bbox", [])),
        "toc_sequence_id": str(matching_entry.get("toc_sequence_id") or ""),
        "toc_entry_index": int(matching_entry.get("sequence_entry_index", matching_entry.get("entry_index", 0)) or 0),
        "toc_text": str(matching_entry.get("text") or ""),
        "toc_outline_index": active_outline_index,
        "heading_profile": "toc_embedded_visual_subheading",
    }
    if matching_entry.get("page_locator_value") is not None:
        section_context["toc_page_locator_value"] = int(matching_entry.get("page_locator_value") or 0)
    return _merge_section_context(section_context, module_context)


def _single_level_outline_marker_belongs_to_active_body_list(
    marker_candidate: Any,
    active_section_context: dict[str, Any] | None,
) -> bool:
    if _single_level_outline_marker_advances_active_root(marker_candidate, active_section_context):
        return False
    marker = getattr(marker_candidate, "marker", None)
    if marker is None:
        return False
    normalized_marker = str(getattr(marker, "normalized_marker", "") or "").strip()
    marker_kind = str(getattr(marker, "marker_kind", "") or "").strip()
    if marker_kind != "decimal_numeric" or not normalized_marker or "." in normalized_marker:
        return False
    context = active_section_context or {}
    if not context:
        return False
    if str(context.get("anchor_source") or "").strip() not in {"toc_body_alignment", "heading", "reference_heading"}:
        return False
    active_outline_index = str(context.get("outline_index") or "").strip()
    if active_outline_index == normalized_marker:
        return False
    return bool(str(context.get("section_title") or context.get("outline_path") or "").strip())


def _single_level_outline_marker_belongs_to_page_list_context(
    marker_candidate: Any,
    text: str,
    section_title: str,
    page_outline_context: dict[str, Any] | None,
    previous_text_block: dict[str, Any] | None,
) -> bool:
    marker = getattr(marker_candidate, "marker", None)
    if marker is None:
        return False
    normalized_marker = str(getattr(marker, "normalized_marker", "") or "").strip()
    marker_kind = str(getattr(marker, "marker_kind", "") or "").strip()
    if marker_kind != "decimal_numeric" or not normalized_marker or "." in normalized_marker:
        return False
    if not normalized_marker.isdigit():
        return False
    if _page_outline_context_is_contents_list(page_outline_context):
        return True
    if _looks_like_numbered_procedure_or_body_list_item(text, section_title):
        return True
    if _previous_text_block_introduces_numbered_list(previous_text_block):
        return True
    context = page_outline_context or {}
    single_markers = list(context.get("single_level_markers", []) or [])
    if len(single_markers) >= 3 and int(normalized_marker) in set(single_markers):
        return True
    return False


def _page_outline_context_is_contents_list(page_outline_context: dict[str, Any] | None) -> bool:
    context = page_outline_context or {}
    return bool(context.get("has_contents_title") and int(context.get("single_level_marker_count", 0) or 0) >= 2)


def _build_page_outline_context(text_blocks: list[dict[str, Any]]) -> dict[str, Any]:
    texts = [
        _clean_text(str(block.get("text") or ""))
        for block in text_blocks
        if str(block.get("block_type", "text") or "text") == "text"
    ]
    compact_texts = [re.sub(r"[^A-Za-z\u4e00-\u9fff]+", "", text).casefold() for text in texts if text]
    has_contents_title = any(
        compact in {"contents", "tableofcontents", "目录", "目錄"}
        or compact.endswith("contents")
        for compact in compact_texts
    )
    single_level_markers: list[int] = []
    decimal_marker_count = 0
    for text in texts:
        marker = parse_outline_heading(text)
        if marker is None:
            continue
        marker_value = str(marker.normalized_marker or "").strip()
        if re.fullmatch(r"\d+", marker_value):
            single_level_markers.append(int(marker_value))
        elif re.fullmatch(r"\d+(?:\.\d+)+", marker_value):
            decimal_marker_count += 1
    return {
        "has_contents_title": has_contents_title,
        "single_level_markers": single_level_markers,
        "single_level_marker_count": len(single_level_markers),
        "decimal_marker_count": decimal_marker_count,
    }


def _looks_like_numeric_heading_fragment(outline_index: str, section_title: str) -> bool:
    outline = str(outline_index or "").strip()
    title = _clean_text(str(section_title or ""))
    if not outline or not title:
        return False
    if re.fullmatch(r"[\d.,%+\-–—/() ]+", title):
        return True
    if re.fullmatch(r"\d+(?:\.\d+)+", outline) and re.fullmatch(r"\d{1,3}", title):
        return True
    lexical_tokens = re.findall(r"[A-Za-z\u4e00-\u9fff]{2,}", title)
    return not lexical_tokens and len(title) <= 8


def _looks_like_numbered_procedure_or_body_list_item(text: str, section_title: str) -> bool:
    cleaned = _clean_text(str(text or ""))
    title = _clean_text(str(section_title or ""))
    if not cleaned or not title:
        return False
    if re.search(r"[.!?;:。！？；：]$", title):
        return True
    lowered = title.lower()
    if re.match(
        r"^(?:place|click|look|use|move|rotate|refocus|add|mix|weigh|label|record|calculate|determine|compare|select|enter|provide|describe|submit|prepare|review|ensure|verify|check|attach|include)\b",
        lowered,
    ):
        return True
    word_count = len(re.findall(r"[A-Za-z][A-Za-z-]*", title))
    if word_count >= 7:
        return True
    return False


def _previous_text_block_introduces_numbered_list(previous_text_block: dict[str, Any] | None) -> bool:
    if not previous_text_block:
        return False
    previous_text = _clean_text(str(previous_text_block.get("text") or ""))
    if not previous_text:
        return False
    if str(previous_text_block.get("semantic_role") or "").strip() == "body_list_item":
        return True
    lowered = previous_text.lower()
    return bool(
        re.search(
            r"(?:following|steps?|procedure|included|include|as follows|below|如下|以下|步骤|程序|包括|包含)\s*[:：]?$",
            lowered,
        )
    )


def _single_level_outline_marker_advances_active_root(
    marker_candidate: Any,
    active_section_context: dict[str, Any] | None,
) -> bool:
    marker = getattr(marker_candidate, "marker", None)
    if marker is None:
        return False
    normalized_marker = str(getattr(marker, "normalized_marker", "") or "").strip()
    marker_kind = str(getattr(marker, "marker_kind", "") or "").strip()
    if marker_kind != "decimal_numeric" or not normalized_marker or "." in normalized_marker:
        return False
    context = active_section_context or {}
    if not context:
        return False
    active_outline_index = str(context.get("outline_index") or "").strip()
    active_root = active_outline_index.split(".", 1)[0] if active_outline_index else ""
    if active_root.isdigit() and normalized_marker.isdigit():
        return int(normalized_marker) == int(active_root) + 1
    return False


def _looks_like_toc_aligned_body_heading_text_block(text_block: dict[str, Any]) -> bool:
    text = _clean_text(str(text_block.get("text") or ""))
    if not text or len(text) > 120:
        return False
    if _toc_body_heading_text_has_list_marker(text):
        return False
    if str(text_block.get("semantic_role") or "").strip() in {
        "page_number",
        "running_header",
        "page_header",
        "running_footer",
        "page_footer",
        "publication_footer",
    }:
        return False
    if _TABLE_LABEL_RE.match(text) or _looks_like_explicit_figure_caption_text(text):
        return False
    if re.search(r"[。；;!?！？]$", text):
        return False
    bbox = _coerce_bbox(text_block.get("bbox"))
    if bbox is None:
        return False
    width = max(1.0, float(bbox[2]) - float(bbox[0]))
    if len(text) > 80 and width > 360:
        return False
    if _STRICT_NUMBERED_SECTION_HEADING_RE.match(text):
        return True
    if re.match(r"^(?:模块|模塊|Module)\s*[0-9IVXLC]+(?:\s*[:：]\s*|\s+).+", text, re.IGNORECASE):
        return True
    if re.match(r"^(?:附录|附錄|Appendix)\s*[A-ZＡ-Ｚ0-9一二三四五六七八九十]+(?:\s*[:：]\s*|\s+.*|$)", text, re.IGNORECASE):
        return True
    cjk_count = len(re.findall(r"[\u4e00-\u9fff]", text))
    return 2 <= cjk_count <= 24 and len(text) <= 60


def _build_toc_body_heading_profile(state: PdfPipelineState) -> dict[str, Any]:
    entries: list[dict[str, Any]] = []
    toc_pages: set[int] = set()
    locator_pairs: list[tuple[int, int]] = []
    for sequence in state.toc_nodes or []:
        if not isinstance(sequence, dict):
            continue
        seq_id = str(sequence.get("toc_sequence_id") or "")
        seq_entries = sequence.get("entries") or []
        for entry in seq_entries:
            if not isinstance(entry, dict):
                continue
            text = _clean_toc_body_heading_title(str(entry.get("text") or ""))
            if not text:
                continue
            page = int(entry.get("page", 0) or 0)
            if page > 0:
                toc_pages.add(page)
            page_locator_value = entry.get("page_locator_value")
            try:
                locator_value = int(page_locator_value) if page_locator_value is not None else None
            except (TypeError, ValueError):
                locator_value = None
            if page > 0 and locator_value is not None:
                locator_pairs.append((page, locator_value))
            entry_profile = {
                "text": text,
                "normalized_title": _normalize_toc_body_heading_text(text),
                "outline_index": str(entry.get("outline_index") or "").strip(),
                "level": int(entry.get("level", 1) or 1),
                "page": page,
                "page_locator_value": locator_value,
                "sequence_entry_index": int(entry.get("sequence_entry_index", entry.get("entry_index", 0)) or 0),
                "entry_index": int(entry.get("entry_index", 0) or 0),
                "toc_sequence_id": seq_id,
            }
            entries.append(entry_profile)
    offsets = [page - locator for page, locator in locator_pairs if locator is not None]
    page_offset = Counter(offsets).most_common(1)[0][0] if offsets else 0
    by_normalized_title: dict[str, list[dict[str, Any]]] = {}
    for entry in entries:
        normalized_title = str(entry.get("normalized_title") or "")
        if normalized_title:
            by_normalized_title.setdefault(normalized_title, []).append(entry)
    return {
        "entries": entries,
        "by_normalized_title": by_normalized_title,
        "toc_pages": toc_pages,
        "page_offset": page_offset,
    }


def _clean_toc_body_heading_title(text: str) -> str:
    cleaned = _clean_text(text)
    if not cleaned:
        return ""
    cleaned = re.sub(r"\.{3,}.*$", "", cleaned).strip()
    cleaned = re.sub(r"\s*错误\s*!\s*未定义书签。?\s*$", "", cleaned, flags=re.IGNORECASE).strip()
    cleaned = re.sub(r"\s+\.{2,}\s*\d+\s*$", "", cleaned).strip()
    return cleaned


def _normalize_toc_body_heading_text(text: str) -> str:
    cleaned = _clean_toc_body_heading_title(text)
    cleaned = re.sub(r"\s+", "", cleaned)
    cleaned = re.sub(r"[.。:：,，;；!！?？()\[\]（）【】<>《》]", "", cleaned)
    return cleaned.casefold()


def _toc_body_heading_titles_compatible(body_title: str, toc_title: str) -> bool:
    body = _normalize_toc_body_heading_text(body_title)
    toc = _normalize_toc_body_heading_text(toc_title)
    if not body or not toc:
        return False
    if body == toc:
        return True
    return (len(body) >= 4 and body in toc) or (len(toc) >= 4 and toc in body)


def _looks_like_regressive_root_heading_candidate(
    outline_index: str,
    active_section_context: dict[str, Any] | None,
) -> bool:
    candidate = str(outline_index or "").strip()
    if not candidate or "." in candidate:
        return False
    if not candidate.isdigit():
        return False
    active_outline_index = str((active_section_context or {}).get("outline_index") or "").strip()
    if not active_outline_index:
        return False
    active_root = active_outline_index.split(".", 1)[0]
    if not active_root.isdigit():
        return False
    return int(candidate) < int(active_root)


def _should_preserve_toc_title_as_text_node(
    toc_block: dict[str, Any],
    title_block: dict[str, Any],
    text_page_nodes: list[dict[str, Any]],
    *,
    page_height: float,
) -> bool:
    title_bbox = list(title_block.get("bbox", []) or [])
    if len(title_bbox) < 4:
        return True
    title_y0 = float(title_bbox[1])
    title_text = _clean_text(str(title_block.get("text", "")))
    if not _compact_text(title_text):
        return False

    nearby_caption_gap = max(28.0, float(page_height or 0.0) * 0.04)
    for node in text_page_nodes:
        node_bbox = list(node.get("bbox", []) or [])
        if len(node_bbox) < 4:
            continue
        node_text = _clean_text(str(node.get("text", "")))
        if not node_text:
            continue
        vertical_gap = title_y0 - float(node_bbox[3])
        if vertical_gap < -2.0 or vertical_gap > nearby_caption_gap:
            continue
        lowered = node_text.lower()
        starts_like_caption = bool(re.match(r"^(?:figure|fig\.?|table)\b", node_text, re.IGNORECASE))
        describes_toc_example = any(token in lowered for token in ("table of contents", "contents", "toc", "目录"))
        if starts_like_caption and describes_toc_example:
            return False

    title_source = str(toc_block.get("title_source") or "").strip()
    if title_source and title_source not in {"text_title_row", "explicit_title_row"}:
        return False
    return True


def _entry_parent_outline_index(outline_index: str) -> str | None:
    candidate = str(outline_index or "").strip().rstrip(".")
    if "." not in candidate:
        return None
    parent = candidate.rsplit(".", 1)[0].strip()
    return parent or None


def _entry_outline_depth(outline_index: str) -> int:
    candidate = str(outline_index or "").strip()
    return len([segment for segment in candidate.split(".") if segment])


def _structure_template_title_candidate(
    text_nodes: list[dict[str, Any]],
    first_entry_index: int,
) -> dict[str, Any] | None:
    for index in range(first_entry_index - 1, -1, -1):
        node = text_nodes[index]
        if str(node.get("block_type", "text") or "text") != "text":
            continue
        text = _clean_text(str(node.get("text", "")))
        if not text:
            continue
        marker = parse_outline_heading(text)
        if marker is not None:
            return None
        role = str(node.get("semantic_role", "") or "").strip()
        if role in {"page_number", "reference_entry", "footnote", "footnote_continuation"}:
            continue
        return node
    return None


def _structure_template_cluster_bbox(
    title_node: dict[str, Any] | None,
    entries: list[dict[str, Any]],
    note_nodes: list[dict[str, Any]] | None = None,
) -> list[float]:
    bboxes: list[list[float]] = []
    if title_node is not None:
        title_bbox = list(title_node.get("bbox", []) or [])
        if len(title_bbox) == 4:
            bboxes.append(title_bbox)
    for entry in entries:
        bbox = list(entry.get("bbox", []) or [])
        if len(bbox) == 4:
            bboxes.append(bbox)
    for node in note_nodes or []:
        bbox = list(node.get("bbox", []) or [])
        if len(bbox) == 4:
            bboxes.append(bbox)
    return _bbox_union(bboxes)


def _build_structure_template_tree(entries: list[dict[str, Any]]) -> tuple[list[dict[str, Any]], int]:
    nodes_by_outline: dict[str, dict[str, Any]] = {}
    ordered_nodes: list[dict[str, Any]] = []
    for entry in entries:
        outline_index = str(entry.get("outline_index") or "").strip()
        node = {
            "entry_index": int(entry.get("entry_index", 0) or 0),
            "outline_index": outline_index,
            "outline_depth": int(entry.get("outline_depth", 0) or 0),
            "title": entry.get("title"),
            "page": int(entry.get("page", 0) or 0),
            "page_target": None,
            "mapping_status": "template_no_page_target",
            "parent_outline_index": entry.get("parent_outline_index"),
            "children": [],
        }
        nodes_by_outline[outline_index] = node
        ordered_nodes.append(node)

    root_nodes: list[dict[str, Any]] = []
    max_branching_factor = 0
    for node in ordered_nodes:
        parent_outline = str(node.get("parent_outline_index") or "").strip()
        parent_node = nodes_by_outline.get(parent_outline)
        if parent_node is None:
            root_nodes.append(node)
            continue
        parent_node["children"].append(node)

    for node in ordered_nodes:
        child_count = len(node["children"])
        node["child_count"] = child_count
        node["has_children"] = child_count > 0
        max_branching_factor = max(max_branching_factor, child_count)
    return root_nodes, max_branching_factor


def _build_structure_template_from_entries(
    *,
    page_number: int,
    template_index: int,
    title_node: dict[str, Any] | None,
    entries: list[dict[str, Any]],
    external_parent_outline_indices: set[str] | None = None,
    continuation_from: dict[str, Any] | None = None,
    note_nodes: list[dict[str, Any]] | None = None,
) -> dict[str, Any] | None:
    if len(entries) < 4:
        return None

    external_parent_outline_indices = set(external_parent_outline_indices or set())
    outline_depths = [int(entry.get("outline_depth", 0) or 0) for entry in entries]
    if max(outline_depths, default=0) < 2:
        return None

    local_outline_indices = {
        str(entry.get("outline_index") or "").strip()
        for entry in entries
        if str(entry.get("outline_index") or "").strip()
    }
    parent_link_count = sum(
        1
        for entry in entries
        if str(entry.get("parent_outline_index") or "").strip()
        and str(entry.get("parent_outline_index") or "").strip() in local_outline_indices.union(external_parent_outline_indices)
    )
    if parent_link_count < 1 and len({int(depth) for depth in outline_depths}) < 2:
        return None

    root_outline_indices = [
        str(entry.get("outline_index") or "").strip()
        for entry in entries
        if not str(entry.get("parent_outline_index") or "").strip()
        or not any(
            str(parent.get("outline_index") or "").strip() == str(entry.get("parent_outline_index") or "").strip()
            for parent in entries
        )
    ]
    root_prefixes = sorted({outline.split(".", 1)[0] for outline in root_outline_indices if outline})
    title_text = _clean_text(str((title_node or {}).get("text", "") or ""))
    template_id = f"structure_template_{template_index:03d}"
    root_nodes, max_branching_factor = _build_structure_template_tree(entries)
    owned_text_block_ids: list[str] = []
    title_block_id = str((title_node or {}).get("block_id") or "").strip()
    if title_block_id:
        owned_text_block_ids.append(title_block_id)
    for entry in entries:
        owned_text_block_ids.extend(
            str(item).strip()
            for item in entry.get("source_block_ids", []) or []
            if str(item).strip()
        )
    note_blocks: list[dict[str, Any]] = []
    for note_index, note_node in enumerate(note_nodes or [], start=1):
        note_block_id = str(note_node.get("block_id") or "").strip()
        note_text = _clean_text(str(note_node.get("text", "") or ""))
        if not note_text:
            continue
        if note_block_id:
            owned_text_block_ids.append(note_block_id)
        note_blocks.append(
            {
                "note_index": note_index,
                "text": note_text,
                "source_block_id": note_block_id or None,
                "bbox": list(note_node.get("bbox", []) or []),
            }
        )
    continuation_from_id = str((continuation_from or {}).get("structure_template_id") or "").strip()
    continuation_from_page = int((continuation_from or {}).get("page", 0) or 0)
    continuation_from_title = _clean_text(str((continuation_from or {}).get("title") or ""))
    continuation_parent_outlines = sorted(
        {
            str(entry.get("parent_outline_index") or "").strip()
            for entry in entries
            if str(entry.get("parent_outline_index") or "").strip() in external_parent_outline_indices
        },
        key=lambda value: (len(value.split(".")), value),
    )
    is_continuation = bool(continuation_from_id and continuation_parent_outlines)
    return {
        "structure_template_id": template_id,
        "block_type": "structure_template",
        "semantic_role": "structure_template",
        "template_kind": "no_page_outline",
        "page": page_number,
        "bbox": _structure_template_cluster_bbox(title_node, entries, note_nodes),
        "title": title_text or None,
        "title_source_block_id": str((title_node or {}).get("block_id") or "").strip() or None,
        "entry_count": len(entries),
        "entries": entries,
        "note_blocks": note_blocks,
        "owned_text_block_ids": list(dict.fromkeys(owned_text_block_ids)),
        "root_nodes": root_nodes,
        "root_outline_indices": root_outline_indices,
        "root_prefixes": root_prefixes,
        "max_outline_depth": max(outline_depths, default=0),
        "max_branching_factor": max_branching_factor,
        "page_target_policy": "no_page_targets",
        "is_structure_template_continuation": is_continuation,
        "continued_from_structure_template_id": continuation_from_id or None,
        "continued_from_page": continuation_from_page or None,
        "continued_from_title": continuation_from_title or None,
        "continuation_parent_outline_index": continuation_parent_outlines[0] if len(continuation_parent_outlines) == 1 else None,
        "continuation_parent_outline_indices": continuation_parent_outlines,
        "semantic_signals": {
            "numbered_outline_row_count": len(entries),
            "parent_link_count": parent_link_count,
            "outline_depth_count": len({int(depth) for depth in outline_depths}),
            "has_explicit_title": bool(title_text),
            "continuation_parent_link_count": len(continuation_parent_outlines),
            "note_block_count": len(note_blocks),
            "semantic_role_reason": "dense_numbered_outline_without_page_locators",
        },
    }


def _collect_structure_template_note_nodes(
    ordered_nodes: list[dict[str, Any]],
    last_entry_index: int,
) -> list[dict[str, Any]]:
    note_nodes: list[dict[str, Any]] = []
    previous_bottom: float | None = None
    note_started = False
    for node in ordered_nodes[last_entry_index + 1 :]:
        if str(node.get("block_type", "text") or "text") != "text":
            break
        role = str(node.get("semantic_role", "") or "").strip()
        if role in {"page_number", "reference_entry"}:
            continue
        text = _clean_text(str(node.get("text", "") or ""))
        if not text:
            continue
        bbox = list(node.get("bbox", []) or [])
        y0 = float(bbox[1]) if len(bbox) >= 2 else 0.0
        y1 = float(bbox[3]) if len(bbox) >= 4 else y0
        if previous_bottom is not None and y0 - previous_bottom > 42.0:
            break
        starts_note = bool(
            re.match(r"^\s*(?:[*#$+\u2020\u2021]|[a-zA-Z]{1,2}|[ivxlcdmIVXLCDM]{1,6}|\d{1,3})\s*[：:]", text)
        )
        marker = parse_outline_heading(text)
        if not note_started and not starts_note:
            break
        if note_started and marker is not None and not re.search(r"(?:部分|section|see|见第|参见)", text, re.IGNORECASE):
            break
        note_started = True
        note_nodes.append(node)
        previous_bottom = max(previous_bottom or y1, y1)
    return note_nodes


def _structure_template_text_bbox(node: dict[str, Any]) -> tuple[float, float, float, float] | None:
    bbox = _coerce_bbox(node.get("bbox"))
    if bbox is None:
        return None
    return bbox


def _can_absorb_structure_template_entry_continuation(
    *,
    entry_node: dict[str, Any],
    previous_node: dict[str, Any],
    candidate_node: dict[str, Any],
) -> bool:
    if str(candidate_node.get("block_type", "text") or "text") != "text":
        return False
    text = _clean_text(str(candidate_node.get("text", "") or ""))
    if not text:
        return False
    if parse_outline_heading(text) is not None:
        return False
    role = str(candidate_node.get("semantic_role", "") or "").strip()
    if role in {
        "page_number",
        "reference_entry",
        "reference_heading",
        "footnote",
        "footnote_continuation",
        "table_note",
        "figure_legend",
        "image_legend",
        "caption",
        "running_header",
        "running_footer",
        "page_header",
        "page_footer",
        "structure_template_title",
        "structure_template_note",
    }:
        return False

    entry_bbox = _structure_template_text_bbox(entry_node)
    previous_bbox = _structure_template_text_bbox(previous_node)
    candidate_bbox = _structure_template_text_bbox(candidate_node)
    if entry_bbox is None or previous_bbox is None or candidate_bbox is None:
        return False

    previous_height = max(1.0, previous_bbox[3] - previous_bbox[1])
    vertical_gap = candidate_bbox[1] - previous_bbox[3]
    if vertical_gap < -previous_height * 0.35:
        return False
    if vertical_gap > max(18.0, previous_height * 1.35):
        return False

    entry_x0, entry_x1 = entry_bbox[0], entry_bbox[2]
    candidate_x0, candidate_x1 = candidate_bbox[0], candidate_bbox[2]
    if candidate_x1 <= entry_x0:
        return False
    if candidate_x0 < entry_x0 - 8.0:
        return False
    if candidate_x0 > entry_x1 + 18.0:
        return False

    if re.search(r"[。.!?！？]\s*$", str(previous_node.get("text") or "")):
        return False
    return True


def _merge_structure_template_entry_continuation_text(base: str, continuation: str) -> str:
    base_text = _clean_text(base)
    continuation_text = _clean_text(continuation)
    if not base_text:
        return continuation_text
    if not continuation_text:
        return base_text
    if re.search(r"[\u4e00-\u9fff]$", base_text) and re.match(r"^[\u4e00-\u9fff]", continuation_text):
        return f"{base_text}{continuation_text}"
    if base_text.endswith(("-", "\u2010", "\u2011", "\u2012", "\u2013")):
        return f"{base_text.rstrip('-\u2010\u2011\u2012\u2013')}{continuation_text}"
    return f"{base_text} {continuation_text}"


def _structure_template_entry_with_continuations(
    *,
    page_number: int,
    entry_index: int,
    node_index: int,
    node: dict[str, Any],
    marker: Any,
    next_entry_node_index: int | None,
    ordered_nodes: list[dict[str, Any]],
    parent_outline: str | None,
) -> dict[str, Any]:
    source_block_id = str(node.get("block_id") or "").strip()
    source_block_ids = [source_block_id] if source_block_id else []
    raw_text = _clean_text(str(node.get("text", "") or ""))
    title = _clean_text(str(marker.title or ""))
    bbox_parts: list[list[float]] = []
    node_bbox = list(node.get("bbox", []) or [])
    if len(node_bbox) == 4:
        bbox_parts.append(node_bbox)

    previous_node = node
    stop_index = next_entry_node_index if next_entry_node_index is not None else len(ordered_nodes)
    for continuation_node in ordered_nodes[node_index + 1 : stop_index]:
        if not _can_absorb_structure_template_entry_continuation(
            entry_node=node,
            previous_node=previous_node,
            candidate_node=continuation_node,
        ):
            if previous_node is node:
                continue
            break
        continuation_text = _clean_text(str(continuation_node.get("text", "") or ""))
        raw_text = _merge_structure_template_entry_continuation_text(raw_text, continuation_text)
        title = _merge_structure_template_entry_continuation_text(title, continuation_text)
        continuation_block_id = str(continuation_node.get("block_id") or "").strip()
        if continuation_block_id:
            source_block_ids.append(continuation_block_id)
        continuation_bbox = list(continuation_node.get("bbox", []) or [])
        if len(continuation_bbox) == 4:
            bbox_parts.append(continuation_bbox)
        previous_node = continuation_node

    outline_index = marker.normalized_marker
    return {
        "entry_index": entry_index,
        "outline_index": outline_index,
        "outline_depth": _entry_outline_depth(outline_index),
        "title": title,
        "text": title,
        "raw_text": raw_text,
        "page": page_number,
        "page_target": None,
        "mapping_status": "template_no_page_target",
        "parent_outline_index": parent_outline,
        "source_block_id": source_block_id or None,
        "source_block_ids": list(dict.fromkeys(source_block_ids)),
        "bbox": _bbox_union(bbox_parts),
    }


def _build_page_structure_templates(
    *,
    page_number: int,
    text_page_nodes: list[dict[str, Any]],
    next_template_index: int,
    previous_structure_template: dict[str, Any] | None = None,
) -> tuple[list[dict[str, Any]], int]:
    ordered_nodes = sorted(
        [node for node in text_page_nodes if str(node.get("block_type", "text") or "text") == "text"],
        key=lambda node: (
            float((node.get("bbox") or [0.0, 0.0, 0.0, 0.0])[1]),
            float((node.get("bbox") or [0.0, 0.0, 0.0, 0.0])[0]),
        ),
    )
    if not ordered_nodes:
        return [], next_template_index

    candidate_rows: list[tuple[int, dict[str, Any], Any]] = []
    for index, node in enumerate(ordered_nodes):
        if str(node.get("semantic_role", "") or "").strip() not in {"section_heading", ""}:
            continue
        marker = parse_outline_heading(node.get("text"))
        if marker is None or marker.marker_kind != "decimal_numeric":
            continue
        if marker.normalized_marker.count(".") < 1:
            continue
        if re.search(r"\.{2,}\s*\d+\s*$", str(node.get("text") or "")):
            continue
        candidate_rows.append((index, node, marker))

    clusters: list[list[tuple[int, dict[str, Any], Any]]] = []
    current: list[tuple[int, dict[str, Any], Any]] = []
    previous_bottom: float | None = None
    for row in candidate_rows:
        _, node, _ = row
        bbox = list(node.get("bbox", []) or [])
        y0 = float(bbox[1]) if len(bbox) >= 2 else 0.0
        y1 = float(bbox[3]) if len(bbox) >= 4 else y0
        if current and previous_bottom is not None and y0 - previous_bottom > 38.0:
            clusters.append(current)
            current = []
        current.append(row)
        previous_bottom = max(previous_bottom or y1, y1)
    if current:
        clusters.append(current)

    templates: list[dict[str, Any]] = []
    consumed_block_ids: set[str] = set()
    previous_outline_indices = {
        str(entry.get("outline_index") or "").strip()
        for entry in (previous_structure_template or {}).get("entries", []) or []
        if str(entry.get("outline_index") or "").strip()
    }
    previous_page = int((previous_structure_template or {}).get("page", 0) or 0)
    can_continue_previous = bool(previous_outline_indices and previous_page == page_number - 1)
    for cluster in clusters:
        if len(cluster) < 4:
            continue
        first_index = cluster[0][0]
        last_index = cluster[-1][0]
        title_node = _structure_template_title_candidate(ordered_nodes, first_index)
        entries: list[dict[str, Any]] = []
        outline_seen: set[str] = set()
        cluster_outlines = {row[2].normalized_marker for row in cluster}
        external_parent_outlines: set[str] = set()
        for entry_index, (_node_index, node, marker) in enumerate(cluster, start=1):
            outline_index = marker.normalized_marker
            if outline_index in outline_seen:
                continue
            outline_seen.add(outline_index)
            parent_outline = _entry_parent_outline_index(outline_index)
            if parent_outline and parent_outline not in cluster_outlines and not (
                can_continue_previous and parent_outline in previous_outline_indices
            ):
                parent_outline = None
            if parent_outline and parent_outline in previous_outline_indices:
                external_parent_outlines.add(parent_outline)
            next_entry_node_index = None
            for following_node_index, _following_node, following_marker in cluster[entry_index:]:
                if following_marker.normalized_marker in outline_seen:
                    continue
                next_entry_node_index = following_node_index
                break
            entries.append(
                _structure_template_entry_with_continuations(
                    page_number=page_number,
                    entry_index=entry_index,
                    node_index=_node_index,
                    node=node,
                    marker=marker,
                    next_entry_node_index=next_entry_node_index,
                    ordered_nodes=ordered_nodes,
                    parent_outline=parent_outline,
                )
            )
        note_nodes = _collect_structure_template_note_nodes(ordered_nodes, last_index)
        template = _build_structure_template_from_entries(
            page_number=page_number,
            template_index=next_template_index,
            title_node=title_node,
            entries=entries,
            external_parent_outline_indices=external_parent_outlines,
            continuation_from=previous_structure_template if external_parent_outlines else None,
            note_nodes=note_nodes,
        )
        if template is None:
            continue
        next_template_index += 1
        templates.append(template)
        for entry in entries:
            consumed_block_ids.update(str(item).strip() for item in entry.get("source_block_ids", []) or [] if str(item).strip())
        title_block_id = str((title_node or {}).get("block_id") or "").strip()
        if title_block_id:
            consumed_block_ids.add(title_block_id)
        for note_node in note_nodes:
            note_block_id = str(note_node.get("block_id") or "").strip()
            if note_block_id:
                consumed_block_ids.add(note_block_id)

    if consumed_block_ids:
        for node in text_page_nodes:
            block_id = str(node.get("block_id") or "").strip()
            if block_id not in consumed_block_ids:
                continue
            if str(node.get("semantic_role", "") or "").strip() == "section_heading":
                node["semantic_role"] = "structure_template_entry"
                node["unit_role"] = "metadata"
            elif block_id and any(str(template.get("title_source_block_id") or "").strip() == block_id for template in templates):
                node["semantic_role"] = "structure_template_title"
                node["unit_role"] = "metadata"
            elif block_id and any(
                block_id
                in {
                    str(note.get("source_block_id") or "").strip()
                    for note in template.get("note_blocks", []) or []
                }
                for template in templates
            ):
                node["semantic_role"] = "structure_template_note"
                node["unit_role"] = "metadata"

    return templates, next_template_index


def _mark_structure_template_owned_text_evidence(
    text_evidence: list[dict[str, Any]],
    templates: list[dict[str, Any]],
) -> None:
    if not text_evidence or not templates:
        return
    title_ids = {
        str(template.get("title_source_block_id") or "").strip()
        for template in templates
        if str(template.get("title_source_block_id") or "").strip()
    }
    entry_ids = {
        str(block_id).strip()
        for template in templates
        for block_id in template.get("owned_text_block_ids", []) or []
        if str(block_id).strip()
    } - title_ids
    note_ids = {
        str(note.get("source_block_id") or "").strip()
        for template in templates
        for note in template.get("note_blocks", []) or []
        if str(note.get("source_block_id") or "").strip()
    }
    note_ids.update(
        str(note.get("source_block_id") or "").strip()
        for template in templates
        for note_group_key in ("leading_continuation_note_blocks", "leading_detached_note_blocks")
        for note in template.get(note_group_key, []) or []
        if isinstance(note, dict) and str(note.get("source_block_id") or "").strip()
    )
    entry_ids -= note_ids
    if not title_ids and not entry_ids and not note_ids:
        return
    for evidence in text_evidence:
        source_id = str(evidence.get("source_id") or "").strip()
        if not source_id:
            continue
        if source_id in title_ids:
            evidence["semantic_role"] = "structure_template_title"
            target_role = "metadata"
        elif source_id in entry_ids:
            evidence["semantic_role"] = "structure_template_entry"
            target_role = "metadata"
        elif source_id in note_ids:
            evidence["semantic_role"] = "structure_template_note"
            target_role = "metadata"
        else:
            continue
        evidence["unit_role"] = target_role
        evidence["fact_extraction_eligible"] = False
        for segment in evidence.get("segments", []) or []:
            if isinstance(segment, dict):
                segment["role"] = target_role


def _build_structure_template_content_evidence(template: dict[str, Any]) -> dict[str, Any]:
    template_id = str(template.get("structure_template_id", "")).strip()
    segments: list[dict[str, Any]] = []
    title = str(template.get("title") or "").strip()
    if title:
        segments.append({"role": "title", "text": title})
    for field_index, field in enumerate(template.get("fields", []) or [], start=1):
        field_text = str(field.get("text") or field.get("label") or "").strip()
        if not field_text:
            continue
        segments.append(
            {
                "role": "field",
                "field_index": int(field.get("row_index", field_index) or field_index),
                "text": field_text,
                "label": field.get("label"),
                "value": field.get("value"),
                "data_population": field.get("data_population"),
            }
        )
    for section_index, section in enumerate(template.get("sections", []) or [], start=1):
        section_text = str(section.get("text") or "").strip()
        if not section_text:
            continue
        segments.append(
            {
                "role": section.get("role") or "section",
                "section_index": int(section.get("row_index", section_index) or section_index),
                "text": section_text,
                "data_population": section.get("data_population"),
            }
        )
    for entry in template.get("entries", []) or []:
        outline_index = str(entry.get("outline_index") or "").strip()
        entry_title = str(entry.get("title") or entry.get("text") or "").strip()
        if not outline_index or not entry_title:
            continue
        segments.append(
            {
                "role": "entry",
                "entry_index": int(entry.get("entry_index", 0) or 0),
                "text": f"{outline_index} {entry_title}",
                "outline_index": outline_index,
                "outline_depth": int(entry.get("outline_depth", 0) or 0),
                "page_target": None,
                "mapping_status": "template_no_page_target",
                "parent_outline_index": entry.get("parent_outline_index"),
            }
        )
    for note_index, note in enumerate(template.get("note_blocks", []) or [], start=1):
        note_text = str(note.get("text") or "").strip()
        if not note_text:
            continue
        segments.append(
            {
                "role": "note",
                "note_index": int(note.get("note_index", note_index) or note_index),
                "text": note_text,
            }
        )
    for ref_index, ref in enumerate(template.get("local_note_refs", []) or [], start=1):
        marker = str(ref.get("marker") or "").strip()
        anchor_text = str(ref.get("anchor_text") or "").strip()
        note_text = str(ref.get("note_text") or "").strip()
        if not marker or not anchor_text or not note_text:
            continue
        segments.append(
            {
                "role": "local_note_ref",
                "ref_index": ref_index,
                "marker": marker,
                "text": f"{anchor_text} -> {marker}: {note_text}",
                "anchor_text": anchor_text,
                "note_text": note_text,
            }
        )
    evidence = {
        "evidence_id": f"ce_structure_template_{template_id}",
        "source_type": "structure_template",
        "source_id": template_id,
        "page": int(template.get("page", 0) or 0),
        "bbox": list(template.get("bbox", []) or []),
        "semantic_role": "structure_template",
        "content_text": _join_content_segments(segments),
        "segments": segments,
        "title": title,
        "template_kind": template.get("template_kind"),
        "template_profile": template.get("template_profile"),
        "ownership_domain": template.get("ownership_domain"),
        "data_population": template.get("data_population"),
        "page_target_policy": template.get("page_target_policy"),
        "entry_count": int(template.get("entry_count", 0) or 0),
        "local_note_refs": [dict(ref) for ref in template.get("local_note_refs", []) or []],
        "composite_object": deepcopy(template.get("composite_object", {}) or {}),
    }
    _copy_metadata_reference_edges_to_evidence(evidence, template)
    _project_owned_text_metadata_reference_edges(
        evidence,
        source_object=template,
        target_object_type="structure_template",
        target_object_id=template_id,
    )
    return evidence


def _copy_metadata_reference_edges_to_evidence(evidence: dict[str, Any], source: dict[str, Any]) -> None:
    return _postprocess_ownership._copy_metadata_reference_edges_to_evidence(evidence, source)


def _project_owned_text_metadata_reference_edges(
    evidence: dict[str, Any],
    *,
    source_object: dict[str, Any],
    target_object_type: str,
    target_object_id: str,
) -> None:
    return _postprocess_ownership._project_owned_text_metadata_reference_edges(
        evidence,
        source_object=source_object,
        target_object_type=target_object_type,
        target_object_id=target_object_id,
    )


def validate_ownership_graph_invariants(blocks: list[dict[str, Any]]) -> list[dict[str, Any]]:
    return _postprocess_ownership.validate_ownership_graph_invariants(blocks)


