def _can_absorb_algorithm_line(
    consumed_blocks: list[dict[str, Any]],
    candidate_block: dict[str, Any],
) -> bool:
    if not consumed_blocks:
        return False
    candidate_text = _clean_text(str(candidate_block.get("text", "")))
    if not candidate_text or _looks_like_algorithm_boundary_text(candidate_text):
        return False
    previous_block = consumed_blocks[-1]
    previous_text = _clean_text(str(previous_block.get("text", "")))
    if not _algorithm_same_lane(consumed_blocks[0], candidate_block):
        return False
    max_gap = max(
        16.0,
        _bbox_height(list(previous_block.get("bbox", []))) * 1.75,
        _bbox_height(list(candidate_block.get("bbox", []))) * 1.75,
    )
    if _algorithm_vertical_gap(previous_block, candidate_block) > max_gap:
        return False
    if _looks_like_algorithm_body_line(candidate_text):
        return True
    if _algorithm_line_is_opener(previous_text):
        return True
    if _algorithm_line_is_open_ended(previous_text):
        return True
    previous_bbox = list(previous_block.get("bbox", []))
    candidate_bbox = list(candidate_block.get("bbox", []))
    if len(previous_bbox) >= 4 and len(candidate_bbox) >= 4:
        if float(candidate_bbox[0]) >= float(previous_bbox[0]) + 10.0:
            return True
    return False


def _build_algorithm_text_block(
    consumed_blocks: list[dict[str, Any]],
    *,
    algorithm_id: str,
    algorithm_ref: str,
    title: str,
    continued_from_previous_page: bool,
    continues_to_next_page: bool,
) -> dict[str, Any]:
    bbox = _bbox_union([list(block.get("bbox", [])) for block in consumed_blocks])
    content_lines = [_clean_text(str(block.get("text", ""))) for block in consumed_blocks if _clean_text(str(block.get("text", "")))]
    source_block_ids = [str(block.get("block_id", "")).strip() for block in consumed_blocks if str(block.get("block_id", "")).strip()]
    source_block_indices: list[int] = []
    for block in consumed_blocks:
        source_block_indices.extend(list(block.get("source_block_indices", []) or []))

    algorithm_block = {
        "block_type": "algorithm",
        "block_id": algorithm_id,
        "algorithm_id": algorithm_id,
        "page": int(consumed_blocks[0].get("page", 0) or 0),
        "bbox": bbox,
        "text": "\n".join(content_lines).strip(),
        "content_text": "\n".join(content_lines).strip(),
        "semantic_role": "algorithm_pseudocode",
        "unit_role": "algorithm",
        "algorithm_ref": algorithm_ref,
        "title": title,
        "source": "algorithm-grouping",
        "source_block_ids": source_block_ids,
        "source_block_indices": sorted(set(int(item) for item in source_block_indices)),
        "line_count": len(content_lines),
        "lines": content_lines,
        "continued_from_previous_page": continued_from_previous_page,
        "continues_to_next_page": continues_to_next_page,
    }
    inline_formula_spans = _build_algorithm_inline_formula_spans(algorithm_block)
    if inline_formula_spans:
        algorithm_block["inline_formula_spans"] = inline_formula_spans
    display_text = _build_algorithm_markdown_display_text(algorithm_block)
    if display_text and display_text != algorithm_block["text"]:
        algorithm_block["display_text"] = display_text
        algorithm_block["text_projection"] = "algorithm_inline_math"
    layout_lane = str(consumed_blocks[0].get("layout_lane", "") or "").strip()
    if layout_lane:
        algorithm_block["layout_lane"] = layout_lane
    layout_mode = str(consumed_blocks[0].get("layout_mode", "") or "").strip()
    if layout_mode:
        algorithm_block["layout_mode"] = layout_mode
    if consumed_blocks[0].get("layout_confidence") is not None:
        algorithm_block["layout_confidence"] = float(consumed_blocks[0].get("layout_confidence", 0.0) or 0.0)
    return algorithm_block


def _build_algorithm_projection(text_block: dict[str, Any]) -> dict[str, Any]:
    return _postprocess_algorithms._build_algorithm_projection(text_block)


def _build_algorithm_inline_formula_spans(algorithm_block: dict[str, Any]) -> list[dict[str, Any]]:
    bbox = list(algorithm_block.get("bbox", []) or [])
    spans: list[dict[str, Any]] = []
    seen: set[tuple[str, str, int]] = set()
    for line_index, line in enumerate(algorithm_block.get("lines", []) or []):
        line_text = _clean_text(str(line or ""))
        if not line_text:
            continue
        for source, latex_text in _algorithm_inline_formula_candidates(line_text):
            source = _clean_text(source)
            latex_text = str(latex_text or "").strip()
            if not source or not latex_text:
                continue
            key = (source, latex_text, line_index)
            if key in seen:
                continue
            seen.add(key)
            span_record = _build_inline_formula_span_record(
                content=source,
                bbox=bbox,
                complexity="inline_formula",
                source="pdf_text_layer_algorithm_inline_math_pattern",
            )
            span_record["line_index"] = line_index
            span_record["latex_text"] = latex_text
            span_record["latex_confidence"] = 0.88
            span_record["latex_source"] = "pdf_text_layer_algorithm_inline_math_pattern"
            span_record["latex_render_policy"] = "text_primary_latex_enhancement"
            span_record["latex_validation"] = {
                "accepted": True,
                "score": 0.88,
                "signals": ["text_layer_algorithm_inline_math_pattern", "inline_formula_structure"],
                "issues": [],
            }
            spans.append(span_record)
    full_text = str(algorithm_block.get("text", "") or "")
    for source, latex_text, line_index in _algorithm_multiline_formula_candidates(full_text):
        key = (source, latex_text, line_index)
        if key in seen:
            continue
        seen.add(key)
        span_record = _build_inline_formula_span_record(
            content=source,
            bbox=bbox,
            complexity="inline_formula",
            source="pdf_text_layer_algorithm_inline_math_pattern",
        )
        span_record["line_index"] = line_index
        span_record["latex_text"] = latex_text
        span_record["latex_confidence"] = 0.88
        span_record["latex_source"] = "pdf_text_layer_algorithm_inline_math_pattern"
        span_record["latex_render_policy"] = "text_primary_latex_enhancement"
        span_record["latex_validation"] = {
            "accepted": True,
            "score": 0.88,
            "signals": ["text_layer_algorithm_multiline_math_pattern", "inline_formula_structure"],
            "issues": [],
        }
        spans.append(span_record)
    return spans


def _algorithm_multiline_formula_candidates(text: str) -> list[tuple[str, str, int]]:
    return _postprocess_algorithms._algorithm_multiline_formula_candidates(text)


def _build_algorithm_markdown_display_text(algorithm_block: dict[str, Any]) -> str:
    return _postprocess_algorithms._build_algorithm_markdown_display_text(algorithm_block)


