_DOSE_RESPONSE_VALUE_RE = re.compile(
    r"^(?:-|\+{1,3}|[<>≥≤+-]?\d+(?:\.\d+)?(?:[a-zA-Z])?(?:\*{1,2}|\+{1,2})?|\d+(?:\.\d+)?\(\d+(?:\.\d+)?\)(?:\*{1,2})?|[MF]:?\d+(?:[a-zA-Z])?)$"
)


def _project_genotoxicity_assay_matrix_tables(
    tables: list[dict[str, Any]],
    *,
    page_words_by_page: dict[int, list[Any]],
    document_ast_pages: list[dict[str, Any]] | None = None,
    structure_templates: list[dict[str, Any]] | None = None,
) -> None:
    by_id = {
        str(table.get("table_id") or "").strip(): table
        for table in tables
        if str(table.get("table_id") or "").strip()
    }
    for table in sorted(tables, key=lambda item: (int(item.get("page", 0) or 0), *_node_physical_order_key(item))):
        if str(table.get("semantic_role") or "business_table") != "business_table":
            continue
        parent_id = str(table.get("continued_from_table_id") or table.get("continued_from") or "").strip()
        parent = by_id.get(parent_id)
        parent_projection = (
            (parent.get("semantic_projection_v2") or {}).get("genotoxicity_assay_matrix_projection", {})
            if isinstance(parent, dict)
            else {}
        )
        grid_text = _table_all_grid_text(table)
        compact = _compact_text(grid_text)
        is_dna = all(token in compact for token in (_compact_text("细胞核"), _compact_text("细胞质"), _compact_text("NG"), _compact_text("%IR"), _compact_text("NGIR")))
        is_bacterial_reverse_mutation = _genotoxicity_bacterial_reverse_mutation_evidence(grid_text)
        is_chromosomal_aberration = _genotoxicity_chromosomal_aberration_evidence(grid_text)
        is_micronucleus = _genotoxicity_micronucleus_evidence(grid_text)
        parent_assay_kind = str(parent_projection.get("assay_kind") or "").strip()
        if (
            not is_dna
            and not is_bacterial_reverse_mutation
            and not is_chromosomal_aberration
            and not is_micronucleus
            and parent_assay_kind not in {"dna_repair_matrix", "bacterial_reverse_mutation_matrix", "chromosomal_aberration_matrix", "micronucleus_matrix"}
        ):
            continue
        semantic_grid = _genotoxicity_bacterial_reverse_mutation_semantic_grid(table)
        assay_kind = "bacterial_reverse_mutation_matrix" if len(semantic_grid) >= 2 else ""
        if len(semantic_grid) < 2:
            semantic_grid = _genotoxicity_dna_repair_semantic_grid(table)
            assay_kind = "dna_repair_matrix" if len(semantic_grid) >= 2 else assay_kind
        if len(semantic_grid) < 2:
            semantic_grid = _genotoxicity_chromosomal_aberration_semantic_grid(table)
            assay_kind = "chromosomal_aberration_matrix" if len(semantic_grid) >= 2 else assay_kind
        if len(semantic_grid) < 2:
            semantic_grid = _genotoxicity_micronucleus_semantic_grid(table)
            assay_kind = "micronucleus_matrix" if len(semantic_grid) >= 2 else assay_kind
        if len(semantic_grid) < 2 and parent_projection.get("assay_kind") == "dna_repair_matrix":
            semantic_grid = _genotoxicity_dna_repair_continuation_grid(table)
            assay_kind = "dna_repair_matrix" if len(semantic_grid) >= 2 else assay_kind
        if len(semantic_grid) < 2 and parent_assay_kind == "bacterial_reverse_mutation_matrix":
            semantic_grid = _genotoxicity_bacterial_reverse_mutation_continuation_grid(table, parent=parent)
            assay_kind = "bacterial_reverse_mutation_matrix" if len(semantic_grid) >= 2 else assay_kind
        if len(semantic_grid) < 2 and parent_assay_kind in {"chromosomal_aberration_matrix", "micronucleus_matrix"}:
            semantic_grid = _genotoxicity_same_assay_continuation_grid(table, parent=parent)
            assay_kind = parent_assay_kind if len(semantic_grid) >= 2 else assay_kind
        if len(semantic_grid) < 2:
            continue
        if isinstance(parent, dict) and parent_projection:
            _ensure_table_continuation_backlink(parent, table)
        _apply_genotoxicity_assay_matrix_projection(
            table,
            semantic_grid=semantic_grid,
            assay_kind=assay_kind or "dna_repair_matrix",
            continuation_schema_inherited=bool(parent_projection),
        )
    _bind_preceding_ctd_study_titles_to_genotoxicity_tables(
        tables,
        document_ast_pages=document_ast_pages,
        structure_templates=structure_templates,
    )
    _bind_loose_study_context_blocks_to_genotoxicity_tables(
        tables,
        document_ast_pages=document_ast_pages,
    )


def _genotoxicity_bacterial_reverse_mutation_semantic_grid(table: dict[str, Any]) -> list[list[str]]:
    rows = [
        [_clean_text(str(cell or "")) for cell in row]
        for row in table.get("semantic_grid", []) or table.get("display_grid", []) or table.get("raw_grid", []) or []
        if isinstance(row, list)
    ]
    if len(rows) < 5:
        return []
    text = _clean_text("\n".join(_grid_row_text(row) for row in rows[:6]))
    if not (
        "代谢活化" in text
        and "供试品" in text
        and ("剂量水平" in text or "浓度" in text)
        and "TA98" in text
        and "TA100" in text
        and "WP2" in text
    ):
        return []
    header = ["代谢活化", "供试品", "剂量水平", "TA98", "TA100", "TA1535", "TA1537", "WP2uvrA"]
    projected: list[list[str]] = [header]
    current_activation = ""
    current_subject = ""
    for raw_row in rows:
        row = _normalize_table_row_width(raw_row, max(len(raw_row), 9))
        row_text = _clean_text(" ".join(str(cell or "") for cell in row))
        if not row_text:
            continue
        if any(token in row_text for token in ("剂量水平", "回复突变体", "菌落计数", "TA98", "TA100", "TA1535", "TA1537", "WP2uvrA")):
            continue
        activation = ""
        if "无代谢活化" in row_text:
            activation = "无代谢活化"
        elif "有代谢活化" in row_text:
            activation = "有代谢活化"
        if activation:
            current_activation = activation
        subject = _genotoxicity_bacterial_subject_from_row(row)
        dose = _genotoxicity_bacterial_dose_from_row(row, subject=subject)
        values = _genotoxicity_bacterial_result_values_from_row(row)
        if subject:
            current_subject = subject
        if not values or len(values) < 5:
            sparse_row = _genotoxicity_bacterial_sparse_result_row(
                row,
                activation=current_activation,
                subject=subject or current_subject,
                dose=dose,
            )
            if sparse_row:
                projected.append(sparse_row)
            continue
        if not dose:
            continue
        projected.append([
            current_activation,
            subject or current_subject,
            dose,
            *values[:5],
        ])
    return projected if len(projected) >= 3 else []


def _genotoxicity_bacterial_reverse_mutation_continuation_grid(
    table: dict[str, Any],
    *,
    parent: dict[str, Any] | None,
) -> list[list[str]]:
    parent_grid = parent.get("semantic_grid") if isinstance(parent, dict) else None
    if not isinstance(parent_grid, list) or not parent_grid:
        return []
    header = [_clean_text(str(cell or "")) for cell in parent_grid[0]]
    if header != ["代谢活化", "供试品", "剂量水平", "TA98", "TA100", "TA1535", "TA1537", "WP2uvrA"]:
        return []
    rows = [
        [_clean_text(str(cell or "")) for cell in row]
        for row in table.get("semantic_grid", []) or table.get("display_grid", []) or table.get("raw_grid", []) or []
        if isinstance(row, list)
    ]
    if not rows:
        return []
    current_activation, current_subject = _genotoxicity_parent_bacterial_carry_forward(parent_grid)
    projected: list[list[str]] = [header]
    row_index = 0
    while row_index < len(rows):
        raw_row = rows[row_index]
        row = _normalize_table_row_width(raw_row, max(len(raw_row), 8))
        row_text = _clean_text(" ".join(str(cell or "") for cell in row))
        row_index += 1
        if not row_text:
            continue
        if any(token in row_text for token in ("剂量水平", "回复突变体", "菌落计数", "TA98", "TA100", "TA1535", "TA1537", "WP2uvrA")):
            continue
        activation = ""
        if "无代谢活化" in row_text:
            activation = "无代谢活化"
        elif "有代谢活化" in row_text:
            activation = "有代谢活化"
        if activation:
            current_activation = activation
        subject = _genotoxicity_bacterial_subject_from_row(row)
        if subject:
            current_subject = subject
        dose = _genotoxicity_bacterial_dose_from_row(row, subject=subject or current_subject)
        values = _genotoxicity_bacterial_result_values_from_row(row)
        if len(values) == 4 and row_index < len(rows):
            next_row = _normalize_table_row_width(rows[row_index], max(len(rows[row_index]), 8))
            next_values = _genotoxicity_bacterial_result_values_from_row(next_row)
            if len(next_values) >= 2:
                if dose:
                    dose = f"{dose}/{next_values[0]}"
                values.append(next_values[-1])
                row_index += 1
        if len(values) < 5 or not dose:
            sparse_row = _genotoxicity_bacterial_sparse_result_row(
                row,
                activation=current_activation,
                subject=subject or current_subject,
                dose=dose,
            )
            if sparse_row:
                projected.append(sparse_row)
            continue
        projected.append([current_activation, subject or current_subject, dose, *values[:5]])
    return projected if len(projected) >= 2 else []


def _genotoxicity_parent_bacterial_carry_forward(parent_grid: list[Any]) -> tuple[str, str]:
    activation = ""
    subject = ""
    for row in parent_grid[1:]:
        if not isinstance(row, list) or len(row) < 3:
            continue
        row_activation = _clean_text(str(row[0] or ""))
        row_subject = _clean_text(str(row[1] or ""))
        if row_activation:
            activation = row_activation
        if row_subject:
            subject = row_subject
    return activation, subject


def _genotoxicity_bacterial_reverse_mutation_evidence(text: str) -> bool:
    clean = _clean_text(str(text or ""))
    if not clean:
        return False
    return bool(
        "代谢活化" in clean
        and "供试品" in clean
        and ("剂量水平" in clean or "浓度" in clean)
        and "TA98" in clean
        and "TA100" in clean
        and "WP2" in clean
    )


def _genotoxicity_bacterial_subject_from_row(row: list[str]) -> str:
    for cell in row[:4]:
        text = _clean_text(str(cell or ""))
        if not text:
            continue
        packed_subject, _packed_dose = _genotoxicity_bacterial_packed_subject_dose(text)
        if packed_subject:
            return packed_subject
        if any(token in text for token in ("DMSO", "MM-180801", "硝基", "叠氮", "氨基", "MMS")):
            if "无代谢活化" in text:
                text = _clean_text(text.replace("无代谢活化", ""))
            if "有代谢活化" in text:
                text = _clean_text(text.replace("有代谢活化", ""))
            return text
    return ""


def _genotoxicity_bacterial_dose_from_row(row: list[str], *, subject: str) -> str:
    for index, cell in enumerate(row[:5]):
        text = _clean_text(str(cell or ""))
        if not text:
            continue
        packed_subject, packed_dose = _genotoxicity_bacterial_packed_subject_dose(text)
        if packed_dose and (not subject or packed_subject == subject):
            return packed_dose
        if text == subject:
            continue
        if "无代谢活化" in text or "有代谢活化" in text:
            continue
        if re.search(r"\d", text) and not re.search(r"±|卤", text):
            if any(token in text for token in ("TA98", "TA100", "TA1535", "TA1537", "WP2")):
                continue
            next_text = _clean_text(str(row[index + 1] or "")) if index + 1 < len(row) else ""
            if next_text and re.fullmatch(r"(?:µ|碌)?[uU]?[lL]/皿|µL/皿|µl/皿", next_text):
                return _clean_text(f"{text} {next_text}")
            return text
    return ""


def _genotoxicity_bacterial_packed_subject_dose(text: str) -> tuple[str, str]:
    clean = _clean_text(str(text or ""))
    match = re.match(r"^(?P<subject>.+?)\s+(?P<dose>\d+(?:\.\d+)?(?:[a-zA-Z])?)$", clean)
    if not match:
        return "", ""
    subject = _clean_text(str(match.group("subject") or ""))
    dose = _clean_text(str(match.group("dose") or ""))
    if not subject or not any(token in subject for token in ("DMSO", "MM-", "硝基", "叠氮", "氨基", "MMS")):
        return "", ""
    return subject, dose


def _genotoxicity_bacterial_result_values_from_row(row: list[str]) -> list[str]:
    values: list[str] = []
    for cell in row:
        text = _clean_text(str(cell or ""))
        if not text:
            continue
        if re.fullmatch(r"\d+(?:\.\d+)?(?:±|卤)\d+(?:\.\d+)?|\d+(?:\.\d+)?(?:\*\*)?(?:\*)?", text):
            values.append(text.replace("卤", "±"))
    return values[-5:] if len(values) >= 5 else values


def _genotoxicity_bacterial_sparse_result_row(
    row: list[str],
    *,
    activation: str,
    subject: str,
    dose: str,
) -> list[str]:
    if not subject or not dose:
        return []
    normalized = _normalize_table_row_width(row, max(len(row), 9))
    value_cells = normalized[4:9]
    if not any(_clean_text(str(cell or "")) for cell in value_cells):
        return []
    return [
        _clean_text(activation),
        _clean_text(subject),
        _clean_text(_genotoxicity_bacterial_sparse_dose_with_unit(normalized, dose)),
        *[_clean_text(str(cell or "")) for cell in value_cells],
    ]


def _genotoxicity_bacterial_sparse_dose_with_unit(row: list[str], dose: str) -> str:
    clean_dose = _clean_text(str(dose or ""))
    if not clean_dose:
        return ""
    for index, cell in enumerate(row):
        if _clean_text(str(cell or "")) != clean_dose:
            continue
        next_text = _clean_text(str(row[index + 1] or "")) if index + 1 < len(row) else ""
        if next_text and "/" in next_text and not re.search(r"\d", next_text):
            return _clean_text(f"{clean_dose} {next_text}")
        return clean_dose
    return clean_dose


def _genotoxicity_dna_repair_semantic_grid(table: dict[str, Any]) -> list[list[str]]:
    rows = [
        [_clean_text(str(cell or "")) for cell in row]
        for row in table.get("semantic_grid", []) or table.get("display_grid", []) or table.get("raw_grid", []) or []
        if isinstance(row, list)
    ]
    if len(rows) < 2:
        return []
    text = _compact_text("\n".join(_grid_row_text(row) for row in rows[:3]))
    if not all(token in text for token in (_compact_text("供试品"), _compact_text("剂量"), _compact_text("动物"), _compact_text("时间"), _compact_text("细胞核"), _compact_text("细胞质"), _compact_text("NG"), _compact_text("%IR"), _compact_text("NGIR"))):
        return []
    header = _dna_repair_header()
    data_rows: list[list[str]] = []
    for row in rows[1:]:
        cells = _normalize_table_row_width(row, len(header))
        if sum(1 for cell in cells if re.search(r"\d|[-+]", str(cell or ""))) >= 4:
            data_rows.append([_clean_text(str(cell or "")) for cell in cells])
    return [header, *data_rows] if data_rows else []


def _genotoxicity_dna_repair_continuation_grid(table: dict[str, Any]) -> list[list[str]]:
    rows = [
        [_clean_text(str(cell or "")) for cell in row]
        for row in table.get("semantic_grid", []) or table.get("display_grid", []) or table.get("raw_grid", []) or []
        if isinstance(row, list)
    ]
    header = _dna_repair_header()
    data_rows = [
        _normalize_table_row_width(row, len(header))
        for row in rows
        if _dose_response_row_has_data_values(row, min_values=4)
    ]
    return [header, *data_rows] if data_rows else []


def _dna_repair_header() -> list[str]:
    return [
        "供试品",
        "剂量(mg/kg)",
        "动物数量",
        "时间(h)",
        "细胞核 平均值±SD",
        "细胞质 平均值±SD",
        "NG 平均值±SD",
        "%IR 平均值±SD",
        "NGIR 平均值±SD",
    ]


def _genotoxicity_chromosomal_aberration_evidence(text: str) -> bool:
    clean = _compact_text(str(text or ""))
    if not clean:
        return False
    return bool(
        all(token in clean for token in (_compact_text("代谢活化"), _compact_text("供试品"), _compact_text("细胞毒性")))
        and any(token in clean for token in (_compact_text("平均细胞畸变率"), _compact_text("细胞畸变率")))
        and any(token in clean for token in (_compact_text("Abs/细胞"), _compact_text("Abs")))
        and any(token in clean for token in (_compact_text("多倍体细胞总数"), _compact_text("多倍体")))
    )


def _genotoxicity_chromosomal_aberration_header() -> list[str]:
    return [
        "代谢活化",
        "供试品",
        "浓度(µg/ml)",
        "细胞毒性a(%对照)",
        "平均细胞畸变率%",
        "Abs/细胞",
        "多倍体细胞总数",
    ]


def _genotoxicity_chromosomal_aberration_semantic_grid(table: dict[str, Any]) -> list[list[str]]:
    rows = [
        [_clean_text(str(cell or "")) for cell in row]
        for row in table.get("semantic_grid", []) or table.get("display_grid", []) or table.get("raw_grid", []) or []
        if isinstance(row, list)
    ]
    if len(rows) < 3:
        return []
    text = "\n".join(_grid_row_text(row) for row in rows[:8])
    if not _genotoxicity_chromosomal_aberration_evidence(text):
        return []
    projected: list[list[str]] = [_genotoxicity_chromosomal_aberration_header()]
    current_activation = ""
    current_subject = ""
    for raw_row in rows:
        row = _normalize_table_row_width(raw_row, max(len(raw_row), 9))
        row_text = _clean_text(" ".join(str(cell or "") for cell in row))
        if not row_text:
            continue
        if _genotoxicity_chromosomal_header_or_label_row(row_text):
            continue
        activation = ""
        if "无代谢活化" in row_text:
            activation = "无代谢活化"
        elif "有代谢活化" in row_text:
            activation = "有代谢活化"
        if activation:
            current_activation = activation
        subject = _genotoxicity_chromosomal_subject_from_row(row)
        if subject:
            current_subject = subject
        values = _genotoxicity_chromosomal_values_from_row(row, subject=subject or current_subject)
        if len(values) < 5:
            continue
        projected.append([
            current_activation,
            subject or current_subject,
            *values[:5],
        ])
    return projected if len(projected) >= 3 else []


def _genotoxicity_same_assay_continuation_grid(
    table: dict[str, Any],
    *,
    parent: dict[str, Any] | None,
) -> list[list[str]]:
    parent_grid = parent.get("semantic_grid") if isinstance(parent, dict) else None
    if not isinstance(parent_grid, list) or not parent_grid:
        return []
    header = [_clean_text(str(cell or "")) for cell in parent_grid[0]]
    if header == _genotoxicity_chromosomal_aberration_header():
        return _genotoxicity_chromosomal_aberration_continuation_grid(table, parent_grid=parent_grid)
    if header == _genotoxicity_micronucleus_header():
        return _genotoxicity_micronucleus_continuation_grid(table, parent_grid=parent_grid)
    return []


def _genotoxicity_chromosomal_aberration_continuation_grid(
    table: dict[str, Any],
    *,
    parent_grid: list[Any],
) -> list[list[str]]:
    header = _genotoxicity_chromosomal_aberration_header()
    rows = [
        [_clean_text(str(cell or "")) for cell in row]
        for row in table.get("semantic_grid", []) or table.get("display_grid", []) or table.get("raw_grid", []) or []
        if isinstance(row, list)
    ]
    if not rows:
        return []
    current_activation, current_subject = _genotoxicity_parent_activation_subject(parent_grid)
    projected: list[list[str]] = [header]
    for raw_row in rows:
        row = _normalize_table_row_width(raw_row, max(len(raw_row), len(header)))
        row_text = _clean_text(" ".join(str(cell or "") for cell in row))
        if not row_text or _genotoxicity_chromosomal_header_or_label_row(row_text):
            continue
        activation = ""
        if "无代谢活化" in row_text:
            activation = "无代谢活化"
        elif "有代谢活化" in row_text:
            activation = "有代谢活化"
        if activation:
            current_activation = activation
        subject = _genotoxicity_chromosomal_subject_from_row(row)
        if subject:
            current_subject = subject
        values = _genotoxicity_chromosomal_values_from_row(row, subject=subject or current_subject)
        if len(values) == len(header) - 2 + 1 and values[0] == values[1]:
            values = values[1:]
        if len(values) < 5:
            continue
        projected.append([current_activation, subject or current_subject, *values[:5]])
    return projected if len(projected) >= 2 else []


def _genotoxicity_parent_activation_subject(parent_grid: list[Any]) -> tuple[str, str]:
    activation = ""
    subject = ""
    for row in parent_grid[1:]:
        if not isinstance(row, list) or len(row) < 2:
            continue
        row_activation = _clean_text(str(row[0] or ""))
        row_subject = _clean_text(str(row[1] or ""))
        if row_activation:
            activation = row_activation
        if row_subject:
            subject = row_subject
    return activation, subject


def _genotoxicity_chromosomal_header_or_label_row(text: str) -> bool:
    if any(token in text for token in ("浓度", "细胞毒性", "畸变率", "Abs/细胞", "多倍体", "结构异常")):
        return True
    compact = _compact_text(text)
    return bool(compact in {_compact_text("代谢活化"), _compact_text("供试品")})


def _genotoxicity_chromosomal_subject_from_row(row: list[str]) -> str:
    for cell in row[:4]:
        text = _clean_text(str(cell or ""))
        if not text:
            continue
        if "无代谢活化" in text:
            text = _clean_text(text.replace("无代谢活化", ""))
        if "有代谢活化" in text:
            text = _clean_text(text.replace("有代谢活化", ""))
        if text and not re.fullmatch(r"[-+]?\d+(?:\.\d+)?(?:\*{1,2})?", text) and not _genotoxicity_chromosomal_header_or_label_row(text):
            if any(token in text for token in ("DMSO", "MM-", "EMS", "环磷酰胺", "丝裂霉素", "MMC", "CP", "阳性", "阴性")):
                return text
    return ""


def _genotoxicity_chromosomal_values_from_row(row: list[str], *, subject: str) -> list[str]:
    values: list[str] = []
    for cell in row:
        text = _clean_text(str(cell or ""))
        if not text or text == subject:
            continue
        if "无代谢活化" in text or "有代谢活化" in text:
            continue
        if _genotoxicity_chromosomal_header_or_label_row(text):
            continue
        if re.fullmatch(r"-|[<>≥≤+-]?\d+(?:\.\d+)?(?:\*{1,2})?(?:[a-zA-Z])?", text):
            values.append(text)
    return values


def _genotoxicity_micronucleus_evidence(text: str) -> bool:
    clean = _compact_text(str(text or ""))
    if not clean:
        return False
    return bool(
        all(token in clean for token in (_compact_text("供试品"), _compact_text("动物数量")))
        and any(token in clean for token in (_compact_text("平均%PCE"), _compact_text("%PCE")))
        and any(token in clean for token in (_compact_text("平均%MN-PCE"), _compact_text("MN-PCE")))
    )


def _genotoxicity_micronucleus_header() -> list[str]:
    return [
        "供试品",
        "剂量(mg/kg)",
        "动物数量",
        "平均%PCE (±SD)",
        "平均%MN-PCE (±SD)",
    ]


def _genotoxicity_micronucleus_semantic_grid(table: dict[str, Any]) -> list[list[str]]:
    rows = [
        [_clean_text(str(cell or "")) for cell in row]
        for row in table.get("semantic_grid", []) or table.get("display_grid", []) or table.get("raw_grid", []) or []
        if isinstance(row, list)
    ]
    if len(rows) < 3:
        return []
    text = "\n".join(_grid_row_text(row) for row in rows[:5])
    if not _genotoxicity_micronucleus_evidence(text):
        return []
    return _genotoxicity_micronucleus_rows_from_grid(rows, inherited_subject="")


def _genotoxicity_micronucleus_continuation_grid(
    table: dict[str, Any],
    *,
    parent_grid: list[Any],
) -> list[list[str]]:
    subject = ""
    for row in parent_grid[1:]:
        if isinstance(row, list) and row:
            row_subject = _clean_text(str(row[0] or ""))
            if row_subject:
                subject = row_subject
    rows = [
        [_clean_text(str(cell or "")) for cell in row]
        for row in table.get("semantic_grid", []) or table.get("display_grid", []) or table.get("raw_grid", []) or []
        if isinstance(row, list)
    ]
    return _genotoxicity_micronucleus_rows_from_grid(rows, inherited_subject=subject)


def _genotoxicity_micronucleus_rows_from_grid(rows: list[list[str]], *, inherited_subject: str) -> list[list[str]]:
    header = _genotoxicity_micronucleus_header()
    projected: list[list[str]] = [header]
    current_subject = inherited_subject
    for raw_row in rows:
        row = _normalize_table_row_width(raw_row, max(len(raw_row), len(header)))
        row_text = _clean_text(" ".join(str(cell or "") for cell in row))
        if not row_text:
            continue
        if any(token in row_text for token in ("平均%PCE", "平均%MN-PCE", "剂量(mg/kg)", "动物数量", "供试品")):
            continue
        subject = _genotoxicity_micronucleus_subject_from_row(row)
        if subject:
            current_subject = subject
        values = _genotoxicity_micronucleus_values_from_row(row, subject=subject or current_subject)
        if len(values) < 4:
            continue
        projected.append([subject or current_subject, *values[:4]])
    return projected if len(projected) >= 2 else []


def _genotoxicity_micronucleus_subject_from_row(row: list[str]) -> str:
    for cell in row[:3]:
        text = _clean_text(str(cell or ""))
        if not text:
            continue
        if any(token in text for token in ("溶媒", "MM-", "环磷酰胺", "阳性", "阴性")):
            return text
    return ""


def _genotoxicity_micronucleus_values_from_row(row: list[str], *, subject: str) -> list[str]:
    values: list[str] = []
    for cell in row:
        text = _clean_text(str(cell or ""))
        if not text or text == subject:
            continue
        if re.fullmatch(r"[<>≥≤+-]?\d+(?:\.\d+)?(?:[a-zA-Z])?|\d+(?:\.\d+)?(?:±|卤)\d+(?:\.\d+)?(?:\*{1,2})?", text):
            values.append(text.replace("卤", "±"))
    return values


def _apply_genotoxicity_assay_matrix_projection(
    table: dict[str, Any],
    *,
    semantic_grid: list[list[str]],
    assay_kind: str,
    continuation_schema_inherited: bool,
) -> None:
    _apply_semantic_grid_projection_common(
        table,
        semantic_grid=semantic_grid,
        source="genotoxicity_assay_matrix_projection",
    )
    projection = dict(table.get("semantic_projection_v2") or {})
    projection["genotoxicity_assay_matrix_projection"] = {
        "source": "genotoxicity_assay_matrix_projection",
        "semantic_profile": "genotoxicity_assay_matrix",
        "assay_kind": assay_kind,
        "logical_column_count": len(semantic_grid[0]),
        "logical_row_count": len(semantic_grid),
        "continuation_schema_inherited": continuation_schema_inherited,
        "coverage_audit": _semantic_projection_coverage_audit(
            table,
            semantic_grid=semantic_grid,
            source="genotoxicity_assay_matrix_projection",
        ),
    }
    table["semantic_projection_v2"] = projection
    table.setdefault("semantic_repairs", []).append(
        {
            "repair": "genotoxicity_assay_matrix_projection",
            "semantic_profile": "genotoxicity_assay_matrix",
            "assay_kind": assay_kind,
            "confidence": 0.88,
        }
    )


def _ensure_table_continuation_backlink(parent: dict[str, Any], child: dict[str, Any]) -> None:
    parent_id = str(parent.get("table_id") or "").strip()
    child_id = str(child.get("table_id") or "").strip()
    if not parent_id or not child_id:
        return
    child["is_continuation"] = True
    child["continued_from_table_id"] = parent_id
    child.setdefault("continued_from_page", int(parent.get("page", 0) or 0) or None)
    existing = [
        str(item or "").strip()
        for item in parent.get("continued_to", []) or []
        if str(item or "").strip()
    ]
    if child_id not in existing:
        parent["continued_to"] = [*existing, child_id]
        parent.setdefault("semantic_repairs", []).append(
            {
                "repair": "semantic_continuation_backlink_rebuilt",
                "semantic_profile": "genotoxicity_assay_matrix",
                "target_table_id": child_id,
                "confidence": 0.88,
            }
        )


def _bind_preceding_ctd_study_titles_to_genotoxicity_tables(
    tables: list[dict[str, Any]],
    *,
    document_ast_pages: list[dict[str, Any]] | None,
    structure_templates: list[dict[str, Any]] | None = None,
) -> None:
    if not document_ast_pages:
        return
    pages_by_number = {
        int(page.get("page", 0) or 0): page
        for page in document_ast_pages
        if int(page.get("page", 0) or 0)
    }
    for table in sorted(tables, key=_node_physical_order_key):
        projection = (table.get("semantic_projection_v2") or {}).get("genotoxicity_assay_matrix_projection")
        if not isinstance(projection, dict):
            continue
        if str(table.get("title") or "").strip():
            continue
        page_number = int(table.get("page", 0) or 0)
        page = pages_by_number.get(page_number)
        if not page:
            continue
        title_node = _nearest_preceding_ctd_study_title_node(table, page.get("blocks", []) or [])
        if title_node is None:
            title_node = _nearest_preceding_ctd_study_title_from_structure_templates(
                table,
                structure_templates or [],
            )
        if title_node is None:
            continue
        title_text = _clean_text(str(title_node.get("text") or ""))
        if not title_text:
            continue
        title_block_id = str(title_node.get("block_id") or "").strip()
        table["title"] = title_text
        table["caption_text"] = title_text
        if title_block_id:
            table["title_source_block_id"] = title_block_id
            table["owned_text_block_ids"] = _append_unique_strings(
                table.get("owned_text_block_ids"),
                [title_block_id],
            )
        else:
            table["owned_texts"] = _append_unique_strings(
                table.get("owned_texts"),
                [title_text],
            )
        table["bbox"] = _bbox_to_list(_bbox_union_loose([table.get("bbox"), title_node.get("bbox")]))
        if str(title_node.get("source_type") or "") != "structure_template_row":
            title_node["semantic_role"] = "structure_template_title"
            title_node["unit_role"] = "metadata"
            title_node["owned_by_table_id"] = str(table.get("table_id") or "").strip() or None
        table.setdefault("semantic_repairs", []).append(
            {
                "repair": "preceding_ctd_study_title_bound_to_genotoxicity_table",
                "source_block_id": title_block_id or None,
                "source_structure_template_id": title_node.get("structure_template_id"),
                "confidence": 0.88,
            }
        )


